html:
{# ================= SALES INVOICE RETURN ONLY ================= #}

{% set return_si = doc %}
{% set original_si = frappe.get_doc("Sales Invoice", doc.return_against) %}
{% set company_doc = frappe.get_doc("Company", doc.company) %}

{% set company_address = frappe.get_doc("Address", doc.company_address)
    if doc.company_address else none %}

{% set buyer_address = (doc.address_display or "")
    | replace("<br>", " ")
    | replace("<br/>", " ")
    | replace("<br />", " ")
    | replace("\n", " ")
    | replace("\r", " ")
%}    

{% set seller_tax_id = company_address.tax_id
    if company_address and company_address.tax_id
    else company_doc.tax_id %}

{#% set buyer_tax_id = buyer_address.tax_id
    if buyer_address and buyer_address.tax_id
    else frappe.db.get_value("Customer", doc.customer, "tax_id")
    or doc.tax_id
    or "-" %#}
    
{% set buyer_tax_id = frappe.db.get_value("Address", doc.customer_address, "tax_id")
    or frappe.db.get_value("Customer", doc.customer, "tax_id")
    or doc.get("tax_id")
    or "-" %}
{# ================= ตั้งค่า (ปรับได้) ================= #}
{% set PAGE_CAP = 16 %}
{% set LAST_CAP = 6 %}
{% set SHOW_DESC = true %}
{% set COPY_LABEL = "ต้นฉบับ" %}

{# ================= สำนักงานใหญ่ / สาขาที่ ================= #}
{% macro branch_label(code, fallback="") -%}
    {%- set c = (code or "") | string | trim -%}
    {%- if c in ["0", "00000"] -%}สำนักงานใหญ่
    {%- elif c -%}สาขาที่ {{ c }}
    {%- else -%}{{ fallback }}
    {%- endif -%}
{%- endmacro %}

{% set seller_branch_code =
    company_address.branch_code if company_address else none %}
    
{#% set buyer_branch_code =
    buyer_address.branch_code if buyer_address
    else frappe.db.get_value("Customer", doc.customer, "branch_code") %#}

{% set buyer_branch_code = frappe.db.get_value("Address", doc.customer_address, "branch_code") if doc.customer_address else "" %}

{% set seller_branch_text =
    branch_label(seller_branch_code, doc.branch or "") %}

{% set buyer_branch_text =
    branch_label(buyer_branch_code, "") %}

{# ================= ยอดตามมาตรา 86/10 ================= #}

{% set amount_1 = frappe.utils.flt(abs(original_si.net_total or 0), 2) %}

{% set amount_3 = frappe.utils.flt(abs(return_si.net_total or 0), 2) %}

{% set amount_2 = frappe.utils.flt(amount_1 - amount_3, 2) %}

{% set amount_4 = frappe.utils.flt(abs(return_si.total_taxes_and_charges or 0), 2) %}

{% set amount_5 = frappe.utils.flt(abs(return_si.grand_total or 0), 2) %}

{# ================= คำนวณน้ำหนัก (ความสูง) ของแต่ละรายการ ================= #}
{% set items = return_si.items or [] %}
{% set total_items = items | length %}
{% set wt = namespace(list=[]) %}
{% for it in items %}
    {% set name = (it.item_name or it.item_code or "") | striptags | trim %}
    {% set desc = (it.description or "") | striptags | trim %}
    {% set w = 1 %}
    {% if SHOW_DESC and desc and desc != name %}{% set w = w + 1 %}{% endif %}
    {% if name | length > 40 %}{% set w = w + 1 %}{% endif %}
    {% set wt.list = wt.list + [w] %}
{% endfor %}

{# ================= แบ่งหน้าตามน้ำหนัก ================= #}
{% set pg = namespace(pages=[], start=0) %}
{% for _i in range(total_items + 1) %}
    {% if pg.start < total_items %}
        {% set left_count = total_items - pg.start %}
        {% set remaining_w = wt.list[pg.start:] | sum %}

        {% if remaining_w <= LAST_CAP %}
            {% set take = left_count %}
        {% else %}
            {% set fill_mode = remaining_w > PAGE_CAP %}
            {% set last_target = [remaining_w // 2, LAST_CAP] | min %}
            {% set acc = namespace(w=0, n=0, stop=false) %}
            {% for w in wt.list[pg.start:] %}
                {% if not acc.stop %}
                    {% if fill_mode %}
                        {% set ok = acc.n == 0 or (acc.w + w) <= PAGE_CAP %}
                    {% else %}
                        {% set ok = (remaining_w - acc.w) > last_target %}
                    {% endif %}
                    {% if ok %}
                        {% set acc.w = acc.w + w %}
                        {% set acc.n = acc.n + 1 %}
                    {% else %}
                        {% set acc.stop = true %}
                    {% endif %}
                {% endif %}
            {% endfor %}
            {% set take = acc.n %}
            {% if take >= left_count %}{% set take = left_count - 1 %}{% endif %}
            {% if take < 1 %}{% set take = left_count %}{% endif %}
        {% endif %}

        {% set pg.pages = pg.pages + [items[pg.start:pg.start + take]] %}
        {% set pg.start = pg.start + take %}
    {% endif %}
{% endfor %}
{% if not pg.pages %}{% set pg.pages = [[]] %}{% endif %}
{% set total_pages = pg.pages | length %}
{% set run = namespace(idx=0, carried=0) %}

<style>
    @page { size: A4; margin: 12mm; }
    body { font-family: Tahoma, Arial, sans-serif; font-size: 13px; color: #333; margin: 0; padding: 0; background: #fff; }

    .cn-page { width: 100%; padding: 5px; box-sizing: border-box; }
    .page-break { page-break-after: always; break-after: page; }

    .header-table, .item-table, .comparison-table, .closing-table, .sign-table { width: 100%; border-collapse: collapse; }
    .header-table td { vertical-align: top; padding: 5px; }

    .company-logo { width: 90px; max-height: 85px; object-fit: contain; margin-right: 12px; }
    .company-info { line-height: 1.55; }
    .company-info h3 { font-size: 17px; margin: 0 0 5px 0; color: #222; }

    .title-box { text-align: right; line-height: 1.45; }
    .title-box h2 { margin: 0 0 2px 0; font-size: 22px; color: #2c3e50; }
    .english-title { color: #c0392b; font-weight: bold; font-size: 15px; }
    .legal-subtitle { font-size: 10px; color: #555; margin-top: 2px; }
    .copy-label { display: inline-block; border: 1px solid #c0392b; color: #c0392b; padding: 1px 8px; font-weight: bold; font-size: 12px; margin-bottom: 4px; }
    .document-meta { margin-top: 6px; font-size: 12px; }
    .document-meta p { margin: 2px 0; }
    .page-no { font-size: 12px; color: #555; }

    .customer-box { border: 1px solid #ccc; padding: 6px 10px; margin: 8px 0; border-radius: 4px; background: #fafafa; line-height: 1.5; }
    .customer-box table { width: 100%; border-collapse: collapse; }
    .customer-box td { vertical-align: top; padding: 2px 3px; }

    .section-title { font-weight: bold; font-size: 13px; margin: 8px 0 5px 0; color: #2c3e50; }

    .item-table th, .item-table td { border: 1px solid #bdc3c7; padding: 4px 6px; }
    .item-table th { background: #2c3e50; color: #fff; text-align: center; font-weight: bold; }
    .item-table td { vertical-align: top; }
    .item-table tr { page-break-inside: avoid; }
    .carry-row td { background: #f4f6f7; font-weight: bold; }

    .continue-note { text-align: right; margin-top: 6px; font-size: 12px; font-style: italic; color: #555; }

    .closing-block { page-break-inside: avoid; break-inside: avoid; margin-top: 8px; }
    .closing-table > tbody > tr > td { vertical-align: top; }

    .comparison-table th, .comparison-table td { border: 1px solid #bdc3c7; padding: 5px 6px; font-size: 12px; }
    .comparison-table th { background: #2c3e50; color: #fff; text-align: center; }
    .comparison-table .difference-row td { font-weight: bold; background: #f1f2f6; }
    .comparison-table .grand-total td { font-weight: bold; background: #e5e8ec; border-top: 2px solid #777; }

    .amount-words, .reason-box { border: 1px solid #ccc; padding: 5px 8px; background: #fafafa; line-height: 1.45; }
    .reason-box { margin-top: 6px; background: #fff; }
    .source-reference { margin-top: 8px; font-size: 10px; color: #666; line-height: 1.5; }

    .validation-warning { margin-top: 8px; padding: 6px; border: 1px solid #c0392b; color: #c0392b; font-size: 11px; }

    .sign-table { margin-top: 16px; }
    .sign-table td { width: 50%; text-align: center; vertical-align: bottom; padding: 0 20px; }
    .signature-line { border-bottom: 1px dotted #333; height: 30px; margin-bottom: 4px; }
    .sign-table p { margin: 3px 0; }

    .legal-footer { margin-top: 8px; padding-top: 4px; border-top: 1px solid #ccc; text-align: center; font-size: 10px; color: #555; }

    .text-right { text-align: right !important; }
    .text-center { text-align: center !important; }
    .small-text { font-size: 10px; color: #555; }
</style>

{% for page_items in pg.pages %}
{% set page_no = loop.index %}
{% set is_first = loop.first %}
{% set is_last = loop.last %}

<div class="cn-page{% if not is_last %} page-break{% endif %}">

    <!-- ===== HEADER (ทุกหน้า) ===== -->
    <table class="header-table">
        <tr>
            <td style="width: 60%;">
                <table style="width: 100%; border-collapse: collapse;">
                    <tr>
                        {% if company_doc.company_logo %}
                        <td style="width: 100px; vertical-align: top;">
                            <img src="{{ frappe.utils.get_url(company_doc.company_logo) }}" class="company-logo">
                        </td>
                        {% endif %}
                        <td class="company-info">
                            <h3>{{ company_doc.company_name or company_doc.name }}</h3>
                            {% if company_address %}
                                {% if company_address.address_line1 %}{{ company_address.address_line1 }}<br>{% endif %}
                                {% if company_address.address_line2 %}{{ company_address.address_line2 }}<br>{% endif %}
                                {{ company_address.city or "" }} {{ company_address.state or "" }}
                                {{ company_address.pincode or "" }} {{ company_address.country or "" }}<br>
                            {% endif %}
                            {% if company_address and company_address.phone %}โทรศัพท์: {{ company_address.phone }}<br>
                            {% elif company_doc.phone_no %}โทรศัพท์: {{ company_doc.phone_no }}<br>{% endif %}
                            {% if company_address and company_address.email_id %}อีเมล: {{ company_address.email_id }}<br>
                            {% elif company_doc.email %}อีเมล: {{ company_doc.email }}<br>{% endif %}
                            <strong>เลขประจำตัวผู้เสียภาษีอากร:</strong> {{ seller_tax_id or "-" }}
                            {% if seller_branch_text %}&nbsp;<strong>{{ seller_branch_text }}</strong>{% endif %}
                        </td>
                    </tr>
                </table>
            </td>
            <td class="title-box" style="width: 40%;">
                <span class="copy-label">{{ COPY_LABEL }}</span>
                <h2>ใบลดหนี้</h2>
                <div class="english-title">CREDIT NOTE</div>
                <div class="legal-subtitle">ออกตามมาตรา 86/10 แห่งประมวลรัษฎากร</div>
                <div class="document-meta">
                    <p><strong>เลขที่ใบลดหนี้:</strong>
                    {{ return_si.name }}
                    </p>
                    <p><strong>วันที่ออกใบลดหนี้:</strong>
                        {{ frappe.utils.formatdate(return_si.posting_date, "dd/MM/yyyy")
                            if return_si.posting_date else "-" }}</p>
                    <p><strong>อ้างอิงใบกำกับภาษีเดิมเลขที่:</strong>
                        {{ original_si.tax_invoice_number or original_si.name or "-" }}
                    </p>
                    <p><strong>ลงวันที่:</strong>
                        {{ frappe.utils.formatdate(original_si.tax_invoice_date or original_si.posting_date, "dd/MM/yyyy") }}
                    </p>
                    <p class="page-no">หน้า {{ page_no }} / {{ total_pages }}</p>
                </div>
            </td>
        </tr>
    </table>

    <!-- ===== BUYER (ทุกหน้า) ===== -->
    <div class="customer-box">
        <table>
            <tr>
                <td style="width: 60%;"><strong>ชื่อผู้ซื้อ / ผู้รับบริการ:</strong>
                    {{ return_si.customer_name or return_si.customer or "-" }}
                </td>
                <td style="width: 40%; text-align: right; white-space: nowrap;"><strong>เลขประจำตัวผู้เสียภาษีอากร:</strong>
                    {{ buyer_tax_id }}
                </td>
            </tr>
            <tr>
                <td><strong>ที่อยู่:</strong>
                    {{ buyer_address | striptags | replace("  ", " ") | trim }}
                </td>
                <td style="text-align: right; white-space: nowrap;">
                    {% if buyer_branch_text %}<strong>สถานประกอบการ:</strong> {{ buyer_branch_text }}{% endif %}
                </td>
            </tr>
        </table>
    </div>

    <!-- ===== ITEMS ===== -->
    <div class="section-title">รายการสินค้าหรือบริการที่ลดหนี้</div>
    <table class="item-table">
        <thead>
            <tr>
                <th style="width: 7%;">ลำดับ</th>
                <th style="width: 39%;">รายการสินค้า / บริการ</th>
                <th style="width: 12%;">จำนวน</th>
                <th style="width: 20%;">ราคาต่อหน่วย<br>(ก่อน VAT)</th>
                <th style="width: 22%;">มูลค่า<br>(ก่อน VAT)</th>
            </tr>
        </thead>
        <tbody>
            {% if not is_first %}
            <tr class="carry-row">
                <td colspan="4" class="text-right">ยอดยกมา</td>
                <td class="text-right">{{ frappe.utils.fmt_money(run.carried, precision=2) }}</td>
            </tr>
            {% endif %}

            {% for it in page_items %}
            {% set run.idx = run.idx + 1 %}
            {% set run.carried = run.carried + abs(it.net_amount or 0) %}
            <tr>
                <td class="text-center">{{ run.idx }}</td>
                <td>
                    {% set name = (it.item_name or it.item_code or "") | striptags | trim %}
                    {% set desc = (it.description or "") | striptags | trim %}
                    <strong>{{ name }}</strong>
                    {% if SHOW_DESC and desc and desc != name %}
                        <br><span class="small-text">{{ desc }}</span>
                    {% endif %}
                </td>
                <td class="text-center">{{ frappe.utils.fmt_money(abs(it.qty or 0), precision=2) }} {{ it.uom or "" }}</td>
                <td class="text-right">{{ frappe.utils.fmt_money(abs(it.net_rate or 0), precision=2) }}</td>
                <td class="text-right">{{ frappe.utils.fmt_money(abs(it.net_amount or 0), precision=2) }}</td>
            </tr>
            {% endfor %}

            {% if total_items == 0 %}
            <tr><td colspan="5" class="text-center">ไม่มีรายการสินค้า</td></tr>
            {% endif %}

            {% if not is_last %}
            <tr class="carry-row">
                <td colspan="4" class="text-right">ยอดยกไป</td>
                <td class="text-right">{{ frappe.utils.fmt_money(run.carried, precision=2) }}</td>
            </tr>
            {% endif %}
        </tbody>
    </table>

    {% if not is_last %}
        <div class="continue-note">
            มีต่อหน้าถัดไป ({{ page_no + 1 }}/{{ total_pages }}) — ใบลดหนี้เลขที่ {{ doc.credit_note_number or "-" }}
        </div>
    {% else %}
    <!-- ===== CLOSING (เฉพาะหน้าสุดท้าย, ห้ามแยกหน้า) ===== -->
    <div class="closing-block">
        <table class="closing-table">
            <tr>
                <td style="width: 52%; padding-right: 10px;">
                    <div class="amount-words">
                        <strong>ยอดลดหนี้รวมทั้งสิ้น (ตัวอักษร):</strong><br>
                        ({{ amount_in_bahttext(amount_5) }})
                    </div>
                    <div class="reason-box">
                        <strong>สาเหตุในการออกใบลดหนี้:</strong><br>
                        {{ doc.remarks  or "-" }}
                    </div>
                </td>
                <td style="width: 48%;">
                    <table class="comparison-table">
                        <thead>
                            <tr>
                                <th style="width: 62%;">รายละเอียดการคำนวณ</th>
                                <th style="width: 38%;">จำนวนเงิน (บาท)</th>
                            </tr>
                        </thead>
                        <tbody>
                            <tr>
                                <td>มูลค่าสินค้า/บริการตามใบกำกับภาษีเดิม (1)</td>
                                <td class="text-right">{{ frappe.utils.fmt_money(amount_1, precision=2) }}</td>
                            </tr>
                            <tr>
                                <td>มูลค่าที่ถูกต้อง (2)</td>
                                <td class="text-right">{{ frappe.utils.fmt_money(amount_2, precision=2) }}</td>
                            </tr>
                            <tr class="difference-row">
                                <td>ผลต่าง (1) − (2) = (3)</td>
                                <td class="text-right">{{ frappe.utils.fmt_money(amount_3, precision=2) }}</td>
                            </tr>
                            <tr>
                                <td>ภาษีมูลค่าเพิ่ม (4)</td>
                                <td class="text-right">{{ frappe.utils.fmt_money(amount_4, precision=2) }}</td>
                            </tr>
                            <tr class="grand-total">
                                <td>รวม (3) + (4) = (5)</td>
                                <td class="text-right">{{ frappe.utils.fmt_money(amount_5, precision=2) }}</td>
                            </tr>
                        </tbody>
                    </table>
                    {% if return_si.discount_amount %}
                    <div class="small-text" style="margin-top: 4px;">
                        * ยอดข้างต้นหักส่วนลด   {{ frappe.utils.fmt_money(abs(return_si.discount_amount), precision=2) }} บาท แล้ว
                    </div>
                    {% endif %}
                </td>
            </tr>
        </table>

        {% if amount_2 < 0 %}
        <div class="validation-warning">
            คำเตือน: มูลค่าที่ลดหนี้เกินมูลค่าตามใบกำกับภาษีเดิม กรุณาตรวจสอบยอดก่อนออกเอกสาร
        </div>
        {% endif %}

        <table class="sign-table">
            <tr>
                <td>
                    <div class="signature-line"></div>
                    <p>ผู้รับใบลดหนี้ / Customer</p>
                    <p>วันที่: _____/_____/_____</p>
                </td>
                <td>
                    <div class="signature-line"></div>
                    <p>ผู้มีอำนาจลงนาม / Authorized Signature</p>
                    <p>วันที่: _____/_____/_____</p>
                </td>
            </tr>
        </table>

        <div class="legal-footer">
            ใบลดหนี้ฉบับนี้ออกตามมาตรา 86/10 แห่งประมวลรัษฎากร
            เพื่อลดมูลค่าตามใบกำกับภาษีเลขที่       {{ original_si.tax_invoice_number or original_si.name or "-" }}
        </div>
    </div>
    {% endif %}

</div>
{% endfor %}
